// claimTokenAllowed enforces D-109 for dated claim token assertions. Structural
// contract/schema checks and live document-integrity checks are separate tests.
func claimTokenAllowed(path, token string) bool {
	if path == "README.md" || path == "docs/ROADMAP.md" {
		return true
	}
	for _, prefix := range []string{"docs/handover/", "docs/ops/", "docs/reviews/", "tests/handover/testdata/"} {
		if strings.HasPrefix(path, prefix) {
			return true
		}
	}
	if path == "docs/node/followup35-diagnostic-and-restart-2026-11-01.md" || strings.HasPrefix(path, "docs/e2e/runs/2026-11-01/followup27/") || strings.HasPrefix(path, "docs/poc/G2-followup25-evidence/") {
		return true
	}
	// Follow-up 30: agent-core 36's dated hand-off (tokens from its own sections
	// only), devstack 29's dated run and netlab 26's per-follow-up evidence tree.
	if path == "docs/node/followup36-restart-and-signals-2026-11-01.md" || strings.HasPrefix(path, "docs/e2e/runs/2026-11-03/followup29/") || strings.HasPrefix(path, "docs/poc/G2-followup26-evidence/") {
		return true
	}
	// Follow-up 37: dated diagnosis and immutable producer archives/design only.
	if path == "docs/e2e/at/isolation/nightly-diagnosis-2026-11-03.md" || strings.HasPrefix(path, "docs/e2e/at/isolation/history/follow-up-17/") || strings.HasPrefix(path, "docs/poc/G2-followup33-design/") {
		return true
	}
	// Follow-up 36: immutable per-follow-up netlab design and evidence only.
	if strings.HasPrefix(path, "docs/poc/G2-followup32-design/") || strings.HasPrefix(path, "docs/poc/G2-followup32-evidence/") {
		return true
	}
	// Follow-up 35: dated updater hand-off and immutable design tree only.
	if path == "docs/updates/node-followup23-2026-11-03.md" || path == "docs/updates/node-followup23-timing-2026-11-03.json" || strings.HasPrefix(path, "docs/poc/G2-followup31-design/") {
		return true
	}
	// Follow-up 34: dated updater and immutable per-follow-up netlab tree.
	if path == "docs/updates/node-followup22-2026-11-03.md" || path == "docs/updates/node-followup22-timing-2026-11-03.json" || strings.HasPrefix(path, "docs/poc/G2-followup30-evidence/") {
		return true
	}
	// Follow-up 33: dated updater and per-follow-up netlab evidence only.
	if path == "docs/updates/node-followup21-2026-11-03.md" || path == "docs/updates/node-followup21-timing-2026-11-03.json" || strings.HasPrefix(path, "docs/poc/G2-followup29-evidence/") {
		return true
	}
	// Follow-up 32: dated updater hand-off, dated devstack analysis and netlab tree.
	if path == "docs/updates/node-followup20-2026-11-03.md" || path == "docs/updates/node-followup20-timing-2026-11-03.json" || strings.HasPrefix(path, "docs/e2e/runs/2026-11-03/followup31/") || strings.HasPrefix(path, "docs/poc/G2-followup28-evidence/") {
		return true
	}
	// Follow-up 31: immutable producer run and per-follow-up evidence only.
	if strings.HasPrefix(path, "docs/e2e/runs/2026-11-03/followup30/") || strings.HasPrefix(path, "docs/poc/G2-followup27-evidence/") {
		return true
	}
	if strings.Contains(path, "/history/") {
		return true
	}
	return strings.HasSuffix(path, "_test.go") && regexp.MustCompile(`^(?:func )?Test[A-Za-z0-9_]+$`).MatchString(token)
}

func requireHandoverClaimTokens(t *testing.T, root, path string, tokens ...string) {
	t.Helper()
	content := readOwnedDoc(t, root, path)
	for _, token := range tokens {
		if !claimTokenAllowed(path, token) {
			t.Errorf("D-109 disallows token pin in %s: %q", path, token)
			continue
		}
		if strings.HasSuffix(path, "_test.go") {
			name := strings.TrimPrefix(token, "func ")
			if !regexp.MustCompile(`(?m)^func ` + regexp.QuoteMeta(name) + `\(`).MatchString(content) {
				t.Errorf("%s missing Go test declaration %s", path, name)
			}
		} else if !strings.Contains(content, token) {
			t.Errorf("%s missing handover claim %q", path, token)
		}
	}
}

