		b, err := io.ReadAll(z)
		if err != nil {
			t.Fatal(err)
		}
		if err = z.Close(); err != nil {
			t.Fatal(err)
		}
		var r struct {
			Run  string `json:"run_id"`
			Rows []struct{ Name, Status string }
		}
